#!/usr/bin/env node
/** Regenerates apps-script/SeedData.gs from seed/encor2026_seed.json (verbatim). */
'use strict';
var fs = require('fs'), path = require('path');
var ROOT = path.join(__dirname, '..');
var json = fs.readFileSync(path.join(ROOT, 'seed', 'encor2026_seed.json'), 'utf8');
JSON.parse(json); // must be valid
fs.writeFileSync(path.join(ROOT, 'apps-script', 'SeedData.gs'),
  '/**\n * GENERATED by dev/build-seed-gs.js from seed/encor2026_seed.json — do not edit by hand.\n' +
  ' * Approved source: Competency Assessment Toolkit + ENCOR2026 Program.\n */\nvar ENCOR_SEED = ' + json.trim() + ';\n');
console.log('wrote apps-script/SeedData.gs');
